#!/usr/bin/env bash
# Question 15: Pod ${Q15_NAME}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q15_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q15_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q15_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
